#define CHECK(x) do{if(!(x)){fprintf(stderr,"Failed at %d: %s\n",__LINE__,#x);exit(1);}}while(0)
#define VK(x) do{VkResult r=(x);CHECK(r==VK_SUCCESS);}while(0)
static void *file(const char *name,size_t *size){FILE*f=fopen(name,"rb");CHECK(f);CHECK(!fseek(f,0,SEEK_END));*size=ftell(f);rewind(f);void*b=malloc(*size);CHECK(b&&fread(b,1,*size,f)==*size);fclose(f);return b;}
static uint32_t memory_type(VkPhysicalDevice p,uint32_t bits,uint32_t flags){VkPhysicalDeviceMemoryProperties m;vkGetPhysicalDeviceMemoryProperties(p,&m);for(uint32_t i=0;i<m.memoryTypeCount;i++)if((bits&(1u<<i))&&(m.memoryTypes[i].propertyFlags&flags)==flags)return i;CHECK(0);return 0;}
static VkDeviceMemory allocate(VkDevice d,VkPhysicalDevice p,VkMemoryRequirements r,uint32_t flags){VkMemoryAllocateInfo a={.sType=VK_STRUCTURE_TYPE_MEMORY_ALLOCATE_INFO,.allocationSize=r.size,.memoryTypeIndex=memory_type(p,r.memoryTypeBits,flags)};VkDeviceMemory m;VK(vkAllocateMemory(d,&a,0,&m));return m;}
static VkBuffer buffer(VkDevice d,VkPhysicalDevice p,size_t size,uint32_t usage,VkDeviceMemory*m,void**mapped){VkBufferCreateInfo b={.sType=VK_STRUCTURE_TYPE_BUFFER_CREATE_INFO,.size=size,.usage=usage,.sharingMode=VK_SHARING_MODE_EXCLUSIVE};VkBuffer out;VK(vkCreateBuffer(d,&b,0,&out));VkMemoryRequirements r;vkGetBufferMemoryRequirements(d,out,&r);*m=allocate(d,p,r,6);VK(vkBindBufferMemory(d,out,*m,0));VK(vkMapMemory(d,*m,0,size,0,mapped));return out;}
static VkShaderModule shader(VkDevice d,const char *name){size_t n;void*b=file(name,&n);VkShaderModuleCreateInfo i={.sType=VK_STRUCTURE_TYPE_SHADER_MODULE_CREATE_INFO,.codeSize=n,.pCode=b};VkShaderModule m;VK(vkCreateShaderModule(d,&i,0,&m));free(b);return m;}
